/**
 * Each lane gets its own curve. The product lane accelerates hard and brakes
 * late, so it arrives with intent; slower lanes hitch along with small stalls.
 */
function laneCurve(s: number, winner: boolean, index: number) {
  if (s <= 0) return 0;
  if (s >= 1) return 1;
  if (winner) return Easing.bezier(0.6, 0, 0.18, 1)(s);
  const k = 3 + (index % 3);
  const a = 0.55 + (index % 2) * 0.2;
  const base = Easing.bezier(0.35, 0, 0.65, 1)(s);
  return base - (a * Math.sin(2 * Math.PI * k * s)) / (2 * Math.PI * k) / 4;
}

const STATEMENT_RE = /^(\d[\d.,]*\s*[×x]?)(.*)$/;

/** Frames after its start until the statement's last glyph has landed. */
function statementSettle(text: string) {
  const match = text.match(STATEMENT_RE);
  return Array.from(match ? match[1] : "").length * 3 + 2 + 22;
}

/**
 * The statement lands glyph by glyph: the figure first, each character rising
 * out of a soft window, then the rest of the line as one piece.
 */
function LandingStatement({
  text,
  t,
  fontSize,
  lead: fill,
  muted,
  fontFamily,
}: {
  text: string;
  t: number;
  fontSize: number;
  /** Top → bottom stops painted through the figure. */
  lead: readonly string[];
  muted: string;
  fontFamily: string;
}) {
  const match = text.match(STATEMENT_RE);
  const lead = match ? match[1] : "";
  const rest = match ? match[2] : text;
  const chars = Array.from(lead);
  const rise = (delay: number) =>
    interpolate(t, [delay, delay + 22], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const restP = rise(chars.length * 3 + 2);
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        whiteSpace: "pre",
        fontFamily,
        fontWeight: 400,
        fontSize,
        lineHeight: 1.1,
        letterSpacing: "-0.05em",
        fontVariantNumeric: "tabular-nums",
      }}
    >
      {chars.map((ch, i) => {
        const p = rise(i * 3);
        return (
          <span
            key={i}
            style={{
              display: "inline-block",
              overflow: "hidden",
              paddingBottom: fontSize * 0.04,
            }}
          >
            <span
              style={{
                display: "inline-block",
                transform: `translateY(${(1 - p) * 0.62 * fontSize}px)`,
                opacity: interpolate(p, [0, 0.5], [0, 1], CLAMP),
                backgroundImage: `linear-gradient(180deg, ${fill[0]} 18%, ${fill[1]} 58%, ${fill[2]} 92%)`,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                color: "transparent",
              }}
            >
              {ch}
            </span>
          </span>
        );
      })}
      <span
        style={{
          color: muted,
          fontWeight: 300,
          letterSpacing: "-0.04em",
          display: "inline-block",
          opacity: restP,
          transform: `translateY(${(1 - restP) * 0.18 * fontSize}px)`,
        }}
      >
        {rest}
      </span>
    </div>
  );
}

function Lane({
  lane,
  index,
  winner,
  t,
  u,
  x0,
  trackW,
  valueW,
  rowH,
  secPerFrame,
  decimals,
  unit,
  accent,
  th,
  hit,
  fg,
  cut,
  fontFamily,
  logo,
}: {
  lane: BenchmarkLane;
  index: number;
  winner: boolean;
  t: number;
  u: number;
  x0: number;
  trackW: number;
  valueW: number;
  rowH: number;
  secPerFrame: number;
  decimals: number;
  unit: string;
  accent: string;
  th: Theme;
  hit: number;
  fg: string;
  cut: string;
  fontFamily: string;
  logo: ReactNode;
}) {
  const gid = `run${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const enter = interpolate(t, [index * 4, index * 4 + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const draw = interpolate(t, [4 + index * 4, 26 + index * 4], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const dur = lane.seconds / secPerFrame;
  const progAt = (frame: number) =>
    laneCurve((frame - START) / dur, winner, index);
  const p = progAt(t);
  const running = t >= START;
  const finished = t - START >= dur;
  const elapsed = Math.min(lane.seconds, Math.max(0, t - START) * secPerFrame);

  // losers dim once the winner lands, but keep moving
  const dim = winner
    ? 1
    : interpolate(t, [hit - 2, hit + 16], [1, 0.42], {
        ...CLAMP,
        easing: EASE_OUT,
      });
  const color = winner ? `url(#${gid})` : th.slow;
  const headFill = winner ? th.head : th.slow;
  const headX = x0 + p * trackW;
  const cy = rowH / 2;

  // the hit
  const hitP = winner
    ? interpolate(t, [hit, hit + 20], [0, 1], { ...CLAMP, easing: EASE_OUT })
    : 0;
  const pulse = winner
    ? interpolate(t, [hit, hit + 5, hit + 16], [1, 1.12, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      })
    : 1;

  // fake motion blur: ghost heads at the previous few frames
  const ghosts = [1, 2, 3].map((g) => x0 + progAt(t - g * 0.8) * trackW);

  const headR = (winner ? 6.5 : 4.5) * u;
  const lineH = (winner ? 4 : 2) * u;
  const isLogo = winner && lane.label.trim().toLowerCase() === "remocn";

  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: index * rowH,
        height: rowH,
        opacity: enter * dim,
        transform: `translateY(${(1 - enter) * 12 * u}px)`,
      }}
    >
      {/* label */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: cy - 14 * u,
          height: 28 * u,
          display: "flex",
          alignItems: "center",
          gap: 10 * u,
          fontFamily,
          fontSize: 23 * u,
          fontWeight: winner ? 500 : 400,
          letterSpacing: "-0.025em",
          color: winner ? fg : th.muted,
        }}
      >
        {isLogo ? (logo ?? <LogoLabel size={25 * u} color={fg} />) : lane.label}
      </div>

      <svg
        width="100%"
        height={rowH}
        style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}
        aria-hidden
      >
        {winner ? (
          <defs>
            <linearGradient
              id={gid}
              gradientUnits="userSpaceOnUse"
              x1={x0}
              x2={x0 + trackW}
              y1={0}
              y2={0}
            >
              <stop offset="0%" stopColor={th.run[0]} />
              <stop offset="40%" stopColor={th.run[1]} />
              <stop offset="78%" stopColor={th.run[2]} />
              <stop offset="100%" stopColor={th.run[3]} />
            </linearGradient>
          </defs>
        ) : null}
        {/* track */}
        <line
          x1={x0}
          x2={x0 + trackW * draw}
          y1={cy}
          y2={cy}
          stroke={th.track}
          strokeWidth={Math.max(1, u)}
        />
        {/* finish tick */}
        <line
          x1={x0 + trackW}
          x2={x0 + trackW}
          y1={cy - 11 * u}
          y2={cy + 11 * u}
          stroke={winner && t >= hit ? accent : th.track}
          strokeWidth={Math.max(1, 1.5 * u)}
          opacity={draw}
        />
        {running && (
          <>
            {winner ? (
              <line
                x1={x0}
                x2={headX}
                y1={cy}
                y2={cy}
                stroke={color}
                strokeWidth={14 * u}
                strokeLinecap="round"
                opacity={0.16}
              />
            ) : null}
            <line
              x1={x0}
              x2={headX}
              y1={cy}
              y2={cy}
              stroke={color}
              strokeWidth={lineH}
              strokeLinecap="round"
            />
            {!finished &&
              ghosts.map((gx, g) => (
                <circle
                  key={g}
                  cx={gx}
                  cy={cy}
                  r={headR}
                  fill={headFill}
                  opacity={0.22 - g * 0.06}
                />
              ))}
            {winner && t >= hit && (
              <circle
                cx={headX}
                cy={cy}
                r={headR + hitP * 26 * u}
                fill="none"
                stroke={accent}
                strokeWidth={1.5 * u}
                opacity={(1 - hitP) * 0.7}
              />
            )}
            <circle
              cx={headX}
              cy={cy}
              r={headR * pulse}
              fill={headFill}
              stroke={cut}
              strokeWidth={2 * u}
            />
          </>
        )}
      </svg>

      {/* clock */}
      <div
        style={{
          position: "absolute",
          right: 0,
          top: cy - 16 * u,
          width: valueW,
          height: 32 * u,
          display: "flex",
          alignItems: "center",
          justifyContent: "flex-end",
          fontFamily: mono,
          fontSize: (winner ? 28 : 24) * u,
          fontWeight: winner ? 500 : 400,
          letterSpacing: "-0.04em",
          fontVariantNumeric: "tabular-nums",
          color: winner ? (finished ? accent : fg) : th.muted,
          transform: `scale(${pulse})`,
          transformOrigin: "100% 50%",
          opacity: interpolate(t, [START - 8, START], [0.35, 1], CLAMP),
        }}
      >
        {elapsed.toFixed(decimals)}
        <span style={{ color: th.muted, marginLeft: u, fontWeight: 400 }}>
          {unit}
        </span>
      </div>
    </div>
  );
}

function BenchmarkRaceBase({
  lanes = DEFAULT_LANES,
  unit = "s",
  statement = "12× faster",
  title = "Cold render, 1080p · median of 50 runs",
  decimals = 2,
  note = "lower is better",
  race = WIN_FRAMES,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  logo,
  scale = 1,
  delay = 0,
  grain = true,
  speed = 1,
  theme = "dark",
}: BenchmarkRaceProps) {
  const tilt = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height } = useSceneConfig();
  const u = height / 720;
  const th: Theme = THEMES[theme];
  const fg = ink ?? th.fg;
  const stage = background ?? th.bg;
  const cut =
    background === undefined || background === "transparent"
      ? th.bg
      : background;
  const hit = START + race;

  const hasHighlight = lanes.some((l) => l.highlight);
  const fastest = lanes.reduce(
    (best, l, i) => (l.seconds < lanes[best].seconds ? i : best),
    0,
  );
  const winnerIndex = hasHighlight
    ? lanes.findIndex((l) => l.highlight)
    : fastest;
  const secPerFrame = lanes[winnerIndex].seconds / race;

  const marginX = Math.round(width * 0.094);
  const labelW = 190 * u;
  const valueW = 150 * u;
  const trackW = width - marginX * 2 - labelW - valueW - 24 * u;
  const rowH = 76 * u;
  const headerH = 48 * u;
  const groupH = headerH + lanes.length * rowH;

  // camera: lanes start centered, glide down to make room for the statement
  const glideAt = (f: number) =>
    interpolate(f, [hit - 4, hit + 38], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const glide = glideAt(t);
  const topStart = (height - groupH) / 2;
  const topEnd = height - 104 * u - groupH;
  // The lanes and the statement are laid out where the glide leaves them; the
  // glide itself is a transform. Layout rounds a box and a baseline to whole
  // pixels, so a group eased by `top` clicks down pixel by pixel.
  const lift = (topStart - topEnd) * (1 - glide);
  const groupScale = 1.04 - 0.04 * glide;
  const lanesSettle = (lanes.length - 1) * 4 + 20;
  // The in-out ease starts so flat that a progress test misses its first
  // frames, so ask whether the glide moves at all.
  const glideMoving = glideAt(t + 1) !== glide || glide !== glideAt(t - 1);
  const lanesMoving = glideMoving || (t > 0 && t < lanesSettle);

  const st = t - (hit + 2);
  const statementMoving =
    glideMoving || (st > 0 && st < statementSettle(statement));
  const stP = interpolate(st, [0, 28], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const statementSize = Math.min(150 * u, width * 0.118);

  const headerP = interpolate(t, [0, 18], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 70% 65% at 35% 30%, ${th.stage}, transparent 75%)`,
        }}
      />
      {th.haze > 0 ? (
        <AbsoluteFill
          style={{
            background: meshHaze(glide),
            opacity: th.haze * stP,
            maskImage:
              "linear-gradient(180deg, #000 0%, rgba(0,0,0,0.6) 38%, transparent 70%)",
          }}
        />
      ) : null}

      <ScaleLayer scale={scale}>
        {/* statement */}
        <div
          style={{
            position: "absolute",
            left: marginX - statementSize * 0.04,
            top: topEnd - statementSize - 70 * u,
            opacity: stP,
            transform: `translateY(${lift + (1 - stP) * 14 * u}px)${tilt(statementMoving)}`,
            filter: stP < 0.98 ? `blur(${(1 - stP) * 6 * u}px)` : undefined,
          }}
        >
          <LandingStatement
            text={statement}
            t={st}
            fontSize={statementSize}
            lead={th.lead}
            muted={th.muted}
            fontFamily={fontFamily}
          />
        </div>

        {/* lanes */}
        <div
          style={{
            position: "absolute",
            left: marginX,
            right: marginX,
            top: topEnd,
            height: groupH,
            transform: `translateY(${lift}px) scale(${groupScale})${tilt(lanesMoving)}`,
            transformOrigin: "0% 50%",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: 0,
              height: headerH,
              display: "flex",
              justifyContent: "space-between",
              fontFamily: mono,
              fontSize: 14 * u,
              fontWeight: 400,
              letterSpacing: "-0.01em",
              color: th.muted,
              opacity: headerP,
              transform: `translateY(${(1 - headerP) * 8 * u}px)`,
            }}
          >
            <span>{title}</span>
            <span style={{ color: th.faint }}>{note}</span>
          </div>
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: headerH,
              height: lanes.length * rowH,
              borderTop: `${Math.max(1, u)}px solid ${th.track}`,
            }}
          >
            {lanes.map((lane, i) => (
              <Lane
                key={lane.label}
                lane={lane}
                index={i}
                winner={i === winnerIndex}
                t={t}
                u={u}
                x0={labelW}
                trackW={trackW}
                valueW={valueW}
                rowH={rowH}
                secPerFrame={secPerFrame}
                decimals={decimals}
                unit={unit}
                accent={accent}
                th={th}
                hit={hit}
                fg={fg}
                cut={cut}
                fontFamily={fontFamily}
                logo={logo}
              />
            ))}
          </div>
        </div>
      </ScaleLayer>

      {grain ? <Grain opacity={th.grain} /> : null}
    </AbsoluteFill>
  );
}

