const ELEMENT_PROP_KEYS = new Set(["theme","unit","statement","title","note","decimals","race","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  unit: "s",
  statement: "12× faster",
  title: "Cold render, 1080p · median of 50 runs",
  note: "lower is better",
  decimals: 2,
  race: 42,
