  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type BenchmarkRaceElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BenchmarkRaceBase>;

const BenchmarkRaceInner = forwardRef<
  HTMLDivElement,
  BenchmarkRaceElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<BenchmarkRace>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BenchmarkRaceBase
          {...(componentProps as unknown as ComponentProps<typeof BenchmarkRaceBase>)}
        />
      </div>
    </Sequence>
  );
});

export const BenchmarkRace = Interactive.withSchema({
  Component: BenchmarkRaceInner,
  componentName: "<BenchmarkRace>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
